import pickle
from collections import defaultdict

allq = pickle.load(open('/tmp/allq.pkl','rb'))

def eval_method(fn, cond_present=False):
    correct=0
    denom=0
    for q in allq:
        samples = q['samples']
        if cond_present:
            anss=set(s['answer'] for s in samples)
            if q['correct_answer'] not in anss:
                continue
        denom+=1
        ans = fn(samples)
        if ans==q['correct_answer']:
            correct+=1
    return correct/denom

def mean_score(samples):
    sums=defaultdict(float); cnt=defaultdict(int)
    for s in samples:
        sums[s['answer']]+=s['score']; cnt[s['answer']]+=1
    means={a: sums[a]/cnt[a] for a in sums}
    return max(means.items(), key=lambda kv: kv[1])[0]

def sum_score(samples):
    sums=defaultdict(float)
    for s in samples:
        sums[s['answer']]+=s['score']
    return max(sums.items(), key=lambda kv: kv[1])[0]

def count_then_meanscore(samples):
    sums=defaultdict(float); cnt=defaultdict(int)
    for s in samples:
        sums[s['answer']]+=s['score']; cnt[s['answer']]+=1
    means={a: sums[a]/cnt[a] for a in sums}
    return max(cnt.items(), key=lambda kv: (kv[1], means[kv[0]]))[0]

def max_score_unique_variant(samples):
    # dedupe: for each variant, only keep highest scoring sample once (avoid double counting same variant's repeated draws)
    best_per_variant = {}
    for s in samples:
        v = s['variant']
        if v not in best_per_variant or s['score']>best_per_variant[v]['score']:
            best_per_variant[v]=s
    sums=defaultdict(float)
    for s in best_per_variant.values():
        sums[s['answer']]+=s['score']
    return max(sums.items(), key=lambda kv: kv[1])[0]

for name, fn in [('mean_score', mean_score), ('sum_score', sum_score), ('count_then_meanscore', count_then_meanscore), ('max_score_unique_variant', max_score_unique_variant)]:
    print(name, 'overall', eval_method(fn), 'cond_present', eval_method(fn, True))
